steps.code:
# Fetch all downloaded songs to build a set of downloaded song IDs
downloaded_songs = []
page_index = 0
while True:
    page = apis.spotify.show_downloaded_songs(access_token=access_token, page_index=page_index, page_limit=20)
    if not page:
        break
    downloaded_songs.extend(page)
    if len(page) < 20:
        break
    page_index += 1

downloaded_ids = {song['song_id'] for song in downloaded_songs}
print(f"Downloaded song IDs: {downloaded_ids}")

