# Find the first downloaded song in the queue starting from the current position
# The queue is cyclic, so we iterate from current position and wrap around
current_pos = None
for song in queue:
    if song.get('is_current') or song.get('is_playing'):
        current_pos = song['position']
        break

if current_pos is None:
    # fallback to position 0 if no current song found
    current_pos = 0

# Build a list of songs in order starting from current_pos
ordered_songs = queue[current_pos:] + queue[:current_pos]

# Find the first song that is downloaded
target_song = None
for song in ordered_songs:
    if song['song_id'] in downloaded_ids:
        target_song = song
        break

if target_song:
    print(f"Found downloaded song: {target_song['title']} (song_id={target_song['song_id']})")
else:
    print("No downloaded song found in the queue")

