steps.code:
# Parse the content line by line.
lines = file_data['content'].split('\n')
archive_songs = []
for line in lines:
    line = line.strip()
    if not line or line.startswith('#'):
        continue
    if line.startswith('- '):
        line = line[2:]
    if ' by ' in line:
        title, artist = line.rsplit(' by ', 1)
        archive_songs.append((title.strip(), artist.strip()))
    else:
        print(f"Unparsed: {line}")
print(f"Archive songs count: {len(archive_songs)}")
for t, a in archive_songs:
    print(f"Title: {t} | Artist: {a}")

