steps.code:
# Parse the file content line by line
lines = file_data['content'].strip().split('\n')
songs_to_archive = []
for line in lines:
    line = line.strip()
    if not line or line.startswith('#'):
        continue
    # Remove leading "- " if present
    if line.startswith('- '):
        line = line[2:]
    if ' by ' in line:
        title, artist = line.rsplit(' by ', 1)
        songs_to_archive.append((title.strip(), artist.strip()))
    else:
        print(f"Could not parse: {line}")

print(f"Parsed {len(songs_to_archive)} songs")
for t, a in songs_to_archive:
    print(f"  {t} by {a}")

