    results = apis.spotify.search_songs(query=query, access_token=spotify_token, page_limit=20)
    # results is a list of songs
    found = None
    for s in results:
        # Check if title and artist match exactly
        if s['title'].lower() == song['title'].lower():
            # Check if any artist matches
            for artist in s['artists']:
                if artist['name'].lower() == song['artist'].lower():
                    found = s
                    break
            if found:
