for playlist in all_playlists:
    pid = playlist["playlist_id"]
    if pid == 654:
        continue
    # Get current songs in this playlist
    pl = apis.spotify.show_playlist(playlist_id=pid, access_token=login_result["access_token"])
    current_song_ids = {song["id"] for song in pl["songs"]}
    to_remove = current_song_ids & archived_ids
    if to_remove:
