# Let's define a function to find the song ID for a given title and artist list.
def find_song_id(title, artists, access_token):
    page_index = 0
    while True:
        results = apis.spotify.search_songs(
            query=title,
            access_token=access_token,
            page_index=page_index,
            page_limit=20
        )
        if not results:
            return None
        for song in results:
            if song['title'].lower() == title.lower():
                song_artists = {a['name'].lower() for a in song['artists']}
                target_artists = {a.lower() for a in artists}
                if song_artists == target_artists:
                    return song['song_id']
        # Check if we got fewer than 20 results, meaning no more pages
        if len(results) < 20:
            return None
        page_index += 1

# Test with first song
song_id = find_song_id('City of Fallen Angels', ['Hazel Winter'], spotify_login['access_token'])
print(song_id)

