# Let's find the song IDs for all songs in songs_to_archive by searching for each one.
# We'll match by title and artist names.

access_token = spotify_login['access_token']
song_ids_to_archive = {}

for song_info in songs_to_archive:
    title = song_info['title']
    artists = song_info['artists']
    query = title + " " + " ".join(artists)
    results = apis.spotify.search_songs(query=query, access_token=access_token)
    # Find exact match
    found = None
    for song in results:
        if song['title'] == title:
            song_artist_names = [a['name'] for a in song['artists']]
            if set(song_artist_names) == set(artists):
                found = song
                break
    if found:
        song_ids_to_archive[title] = found['song_id']
        print(f"Found: {title} -> song_id {found['song_id']}")
