steps.code:
# Define target song IDs from the file
target_song_ids = {295, 324, 22, 245, 320, 92, 299, 4, 278, 69, 219, 298, 265}

# Iterate over all playlists and remove target songs
for playlist in playlists:
    playlist_id = playlist['playlist_id']
    song_ids = playlist['song_ids']
    for song_id in song_ids:
        if song_id in target_song_ids:
            print(f"Removing song {song_id} from playlist {playlist_id}")
            result = apis.spotify.remove_song_from_playlist(playlist_id=playlist_id, song_id=song_id, access_token=spotify_token)
            print(result)

