steps.code:
# Now process all playlists: remove matching songs and add to new playlist 654.
target_titles = {'Secrets of the Heart', 'Sacred Ground', 'Strangers Again', 'Beneath the Surface of Love', 'Whispers of a Forgotten Love', "A Broken Heart's Lament", 'Echoes from the Abyss', 'Lost in the Maze of Your Mind', 'In the Wake of Goodbye', 'The Puzzle of My Heart', 'When Dawn Breaks Without You', 'City of Fallen Angels', 'Crimson Veil'}

playlist_ids = [pl['playlist_id'] for pl in playlists]
added_song_ids = set()

for pl_id in playlist_ids:
    detail = apis.spotify.show_playlist(playlist_id=pl_id, access_token=spotify_token)
    for song in detail['songs']:
        if song['title'] in target_titles:
            print(f"Removing song {song['id']} ({song['title']}) from playlist {pl_id}")
            apis.spotify.remove_song_from_playlist(playlist_id=pl_id, song_id=song['id'], access_token=spotify_token)
            if song['id'] not in added_song_ids:
                print(f"Adding song {song['id']} to playlist 654")
                apis.spotify.add_song_to_playlist(playlist_id=654, song_id=song['id'], access_token=spotify_token)
                added_song_ids.add(song['id'])

